import { test } from 'node:test';
import * as assert from 'node:assert/strict';
import * as fs from 'node:fs';
import * as path from 'node:path';
import * as os from 'node:os';

/**
 * Acceptance test for linux-socket-territory-observation-capcell-fabrication
 * Namespace import used to verify presence and functionality of the observed interface.
 */
import * as CapabilityCell from '../implementation/socket-observation.mjs';

test('exact-loopback-tcp-territory', async (t) => {
    // Setup: create a temporary directory for observation receipt artifacts
    const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'socket-obs-'));

    // GIVEN: an injected Linux socket snapshot and an explicit admissibility policy
    const mockSnapshot = {
        namespace: 'netns:default',
        family: 'AF_INET',
        proto: 'TCP',
        entries: [
            { local: '127.0.0.1', port: 8080, state: 'LISTEN' },
            { local: '127.0.0.1', port: 8081, state: 'ESTABLISHED' }
        ]
    };

    const policy = {
        admissiblePorts: [8080, 8081, 8082, 8083],
        denominator: '4'
    };

    // WHEN: the territory is observed
    const observation = CapabilityCell.observeLinuxSocketTerritory(mockSnapshot, policy);

    // THEN: capacity and occupancy sets are derived from the snapshot
    assert.ok(observation.occupancy, 'Occupancy set is missing');
    assert.equal(observation.occupancy.length, 2);

    // THEN: occupied/admissible and available/admissible are reduced exact fractions
    // Admissible (4), Occupied (2) -> 2/4 -> 1/2
    assert.equal(observation.metrics.occupancyFraction.numerator, '1');
    assert.equal(observation.metrics.occupancyFraction.denominator, '2');

    // Available (2) -> 2/4 -> 1/2
    assert.equal(observation.metrics.availabilityFraction.numerator, '1');
    assert.equal(observation.metrics.availabilityFraction.denominator, '2');

    // THEN: each admissible berth has exact share 1/N with the same referent
    assert.equal(observation.metrics.berthShare.numerator, '1');
    assert.equal(observation.metrics.berthShare.denominator, '4');

    // FORBIDDEN checks
    assert.ok(!JSON.stringify(observation).includes('.'), 'Floating point detected in decimal strings');
});

test('typed-observation-refusal', async (t) => {
    // GIVEN: a namespace that cannot be observed (simulated by missing/malformed input)
    const invalidSnapshot = null;
    const policy = { admissiblePorts: [80], denominator: '1' };

    // WHEN: the operation is invoked
    const result = CapabilityCell.observeLinuxSocketTerritory(invalidSnapshot, policy);

    // THEN: a typed refusal identifies the missing observation
    assert.equal(result.status, 'REFUSAL');
    assert.ok(result.reason.includes('unobservable'), 'Refusal did not identify missing state');

    // THEN: no zero measurement is fabricated
    assert.notEqual(result.metrics, 0, 'Measurement should not be 0');
    assert.strictEqual(result.metrics, undefined, 'Metrics should remain undefined on refusal');
});

/**
 * Finalizing test suite cleanup
 */
process.on('exit', () => {
    // Manual cleanup of tmpDir would happen here if persisted outside of scope
});
